import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Certificates — the replayable derivation","description":"","frontmatter":{},"headers":[],"relativePath":"eqsat/explanation/certificates.md","filePath":"vendored/eqsat/explanation/certificates.md"}`),a={name:`eqsat/explanation/certificates.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="certificates-—-the-replayable-derivation" tabindex="-1">Certificates — the replayable derivation <a class="header-anchor" href="#certificates-—-the-replayable-derivation" aria-label="Permalink to “Certificates — the replayable derivation”">​</a></h1><p>A certificate is the artifact a search produces that outlives the search: a replayable derivation from the source term to the extracted term. The certificate, not the timing, is the claim.</p><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to “The model”">​</a></h2><ul><li><code>Certificate</code> — the derivation: an ordered list of <code>CertStep</code>s (a rule name, the e-class it fired on, the resulting merge) over <code>ProofEdge</code>s.</li><li><code>EGraph.certificate(src, dst, root_eid=...)</code> — extract the derivation the saturated graph witnesses between two terms.</li><li><code>verify_certificate(term, cert, *, strict=False)</code> — replay the certificate <em>standalone</em>: apply each step to the source term and check the claimed result lands in the same class. A certificate that does not replay raises <code>CertificateVerificationError</code> — no trust in the engine that emitted it.</li><li><code>cert_to_data</code> / <code>cert_from_data</code> — the transport form, so a certificate can cross a wire, a cache, or a backend boundary.</li></ul><h2 id="two-places-certificates-do-the-work" tabindex="-1">Two places certificates do the work <a class="header-anchor" href="#two-places-certificates-do-the-work" aria-label="Permalink to “Two places certificates do the work”">​</a></h2><ol><li><strong>Delivery.</strong> Every program the pipeline lowers ships its certificate — <code>search → extract → certify</code> — so downstream consumers verify the derivation, not the optimizer&#39;s reputation. See <a href="/docs/graphopt/tutorials/first-search.html">your first <code>search()</code></a>.</li><li><strong>Admission.</strong> The derivability check in the <a href="/docs/graphopt/explanation/the-gauntlet.html">gauntlet</a> is a certificate replay: <code>verify_law(lhs, rhs, rules)</code> (the domain side, in <code>graphopt</code>&#39;s <code>mlopt_discovery</code>) interns both sides in a fresh small e-graph, saturates under the known laws, and replays the witness <em>in both directions</em> — a merge is a genuine derivation, never a trusted stub. This substrate supplies the e-graph and the replay; the admission policy is the domain&#39;s.</li></ol><h2 id="the-honest-boundary" tabindex="-1">The honest boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The honest boundary”">​</a></h2><p>A certificate proves <em>equality of the derivation</em>, nothing else: it says the extracted program computes the same thing as the source. Whether the extraction was worth it is a <a href="/docs/graphopt/explanation/three-costs.html">measured</a> question the certificate deliberately does not answer.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};